    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is the most significant difference between a "Living Will" and a "Durable Power of Attorney for Healthcare" (DPOA-HC)?', '["Living Wills are for money, DPOA-HC is for health", "A Living Will specifies treatments, while a DPOA-HC designates a person to make decisions", "Only a DPOA-HC is legally binding", "Living Wills are only for patients with cancer"]', 1, 'A Living Will provides specific instructions about treatments (e.g., "no ventilator"), whereas a DPOA-HC (or Healthcare Proxy) names a surrogate to make decisions on the patient''s behalf.'),
    (v_topic_id, 'When does a "Durable Power of Attorney for Healthcare" (DPOA-HC) typically become active?', '["Immediately upon signing", "Only after the patient dies", "When the patient is determined by a physician to lack decision-making capacity", "When the patient reaches age 65"]', 2, 'Advance directives are "contingency" documents that become active only when the patient is no longer able to speak for themselves.'),
    (v_topic_id, 'What is "Prospective Capacity"?', '["The ability to see into the future", "The capacity a patient has at the time they create an advance directive to plan for future incapacity", "The capacity a patient has after they recover from a coma", "The capacity of the doctor to predict a patient''s death"]', 1, 'Prospective capacity is the legal and ethical requirement that a patient must be competent at the time they execute an advance directive for it to be valid.'),
    (v_topic_id, 'A patient has a "Living Will" that says "no tubes." However, they currently have decision-making capacity and tell the doctor, "I changed my mind, put the tube in." What should the doctor do?', '["Follow the Living Will", "Follow the patient''s current verbal instructions", "Wait for the family to decide", "Call the hospital lawyer"]', 1, 'A competent patient''s contemporaneous wishes always override a prior written advance directive. A patient can rescind or modify their advance directive at any time as long as they have capacity.'),
    (v_topic_id, 'Which of the following is a common requirement for an advance directive to be legally valid in most states?', '["It must be signed by a judge", "It must be witnessed by two adults or notarized", "It must be written in the presence of a lawyer", "It must be renewed every year"]', 1, 'Witnessing or notarization is required to ensure that the document was signed voluntarily and by the person identified.'),
    (v_topic_id, 'Can a physician serve as a "Witness" for their own patient''s advance directive?', '["Yes, always", "No, in most states clinicians involved in the patient''s care are prohibited from being witnesses to avoid conflicts of interest", "Only if the patient pays a fee", "Only in the ER"]', 1, 'Ethical and legal guidelines generally prohibit treating clinicians or facility employees from serving as witnesses to prevent potential bias or coercion.'),
    (v_topic_id, 'An "Oral" advance directive (witnessed verbal statements) is:', '["Never legally valid", "Can be considered ''clear and convincing evidence'' of a patient''s wishes in many jurisdictions if made to multiple people over time", "Only valid for children", "Only valid if recorded on a smartphone"]', 1, 'While written documents are preferred, clear and consistent oral statements (e.g., telling your family, "I never want to be on a machine like that") are ethically and often legally significant.'),
    (v_topic_id, 'What is the "Substituted Judgment" standard?', '["The doctor decides what they would do if they were the patient", "The surrogate makes the decision they believe the patient would have made for themselves based on the patient''s known values and previous statements", "The surrogate decides what is best for the family", "The court decides what is fair"]', 1, 'Substituted judgment aims to honor the patient''s autonomy by having the surrogate "step into the patient''s shoes" to make the choice the patient would have made.'),
    (v_topic_id, 'Which of the following is a "Negative" advance directive?', '["A document requesting every possible treatment", "A DNR order", "A request to be buried in a specific cemetery", "None of the above"]', 1, 'A negative directive specifies what the patient does *not* want (e.g., "Do Not Resuscitate").'),
    (v_topic_id, 'The "Patient Self-Determination Act" applies to which healthcare settings?', '["Only private doctors'' offices", "All healthcare facilities that receive Medicare and Medicaid funding", "Only hospices", "Only pediatric hospitals"]', 1, 'The PSDA is a federal law that ensures patients in almost all institutional settings are informed of their right to refuse care and create advance directives.'),
    (v_topic_id, 'A patient''s advance directive uses vague language like "no heroic measures." How should this be interpreted?', '["It should be ignored", "The physician and surrogate must interpret the phrase in the context of the patient''s specific clinical situation and known values", "It always means ''no antibiotics''", "It means ''no blood pressure medication''"]', 1, 'Vague terms require clinical and ethical interpretation. The surrogate''s role is to clarify what those terms meant to the patient.'),
    (v_topic_id, 'Which document is designed specifically for "Emergency Medical Services" (EMS) to follow in the community?', '["A Living Will", "An out-of-hospital DNR or a POLST/MOLST form", "A birth certificate", "A marriage license"]', 1, 'EMS providers generally cannot follow Living Wills or DPOAs; they require specific medical orders like an out-of-hospital DNR or a POLST.'),
    (v_topic_id, 'A patient is incapacitated and has two daughters. One has a DPOA-HC and says "Stop treatment," the other daughter has no document and says "Continue treatment." Whose decision carries legal weight?', '["The one who wants to continue treatment", "The one designated as the DPOA-HC", "The doctor must decide", "The eldest daughter"]', 1, 'The legally designated DPOA-HC (Healthcare Proxy) has the authority to make the decision, overriding other family members who were not designated.'),
    (v_topic_id, 'If a patient has NO advance directive and NO DPOA-HC, who typically becomes the surrogate in most state hierarchies?', '["The doctor", "The next of kin (e.g., spouse, then adult children, then parents)", "The hospital lawyer", "The patient''s best friend"]', 1, 'Most states have "Default Surrogate" laws that establish a hierarchy of family members to make decisions in the absence of a designated proxy.'),
    (v_topic_id, 'What is the primary goal of the "POLST" (Physician Orders for Life-Sustaining Treatment) paradigm?', '["To replace the Living Will", "To translate patient preferences into actionable medical orders that are portable across care settings", "To reduce the hospital budget", "To allow doctors to ignore the patient"]', 1, 'POLST/MOLST forms are actual medical orders that travel with the patient, ensuring their wishes are followed by EMS, nursing homes, and hospitals.'),
    (v_topic_id, 'Can a surrogate "Change their mind" after making a decision for an incapacitated patient?', '["No, never", "Yes, as long as they are still acting in accordance with the patient''s wishes or best interests", "Only if the doctor agrees", "Only if it is a Tuesday"]', 1, 'Surrogates can and do change their minds as new clinical information becomes available, provided they are still fulfilling their ethical duty to the patient.'),
    (v_topic_id, 'In the absence of any known wishes, what is the default "Presumption" in medicine?', '["Presume the patient wants to die", "Presume the patient wants life-sustaining treatment", "Presume the patient wants to be a donor", "Presume the patient has no family"]', 1, 'The "Presumption of Life" means that in emergencies or when wishes are unknown, physicians default to providing life-saving care until more information is available.'),
    (v_topic_id, 'A "Five Wishes" document is an example of:', '["A tax form", "A comprehensive advance directive that includes medical, personal, emotional, and spiritual wishes", "A grocery list", "A funeral plan"]', 1, 'Five Wishes is a popular, user-friendly advance directive that is legally recognized in most states.'),
    (v_topic_id, 'Which of the following is TRUE regarding advance directives across state lines (Reciprocity)?', '["They are never valid outside the state they were signed in", "Many states have laws that recognize valid advance directives from other states, though specific requirements may vary", "You must get a new one every time you cross a border", "Only federal advance directives are valid"]', 1, 'Most states have "reciprocity" provisions, but it is often recommended to update directives when moving to a new state to ensure local compliance.'),
    (v_topic_id, 'A patient with early-stage dementia wants to create an advance directive. Can they?', '["No, they have dementia", "Yes, if they still have the capacity to understand the nature and consequences of the document they are signing", "Only if a judge agrees", "Only if their spouse signs it"]', 1, 'A diagnosis of dementia does not automatically mean a lack of capacity. Patients should be encouraged to complete directives while they still have the ability to do so.'),
    (v_topic_id, 'What is a "Springing" power of attorney in healthcare?', '["One that only works in the spring", "One that only ''springs'' into effect upon a specific event, usually the determination of incapacity", "One that expires after 5 years", "None of the above"]', 1, 'Most healthcare powers of attorney are "springing" because they only become active when the patient can no longer make decisions.'),
    (v_topic_id, 'Which of the following is a "Procedural" requirement for a valid DPOA-HC in many jurisdictions?', '["It must be written in blue ink", "It must be witnessed by someone who is NOT a beneficiary of the patient''s estate", "It must be published in the newspaper", "None of the above"]', 1, 'To prevent conflicts of interest, witnesses often cannot be heirs or beneficiaries of the patient.'),
    (v_topic_id, 'A patient has a "DNR" order but is scheduled for surgery. What is the standard ethical approach to the DNR during the surgery?', '["The DNR is automatically cancelled", "A ''Required Reconsideration'' should occur, where the surgeon and patient discuss if the DNR should be suspended during the perioperative period", "The DNR must stay in effect at all times", "Surgeons don''t follow DNRs"]', 1, 'Because some arrests in the OR are reversible and related to the anesthesia itself, patients and surgeons usually agree to a temporary suspension or modification of the DNR.'),
    (v_topic_id, 'What is the role of a "Court-Appointed Guardian" in end-of-life care?', '["To pay the patient''s bills", "To make medical and/or financial decisions for a person who has been legally declared incompetent and has no other surrogate", "To visit the patient on holidays", "To act as the patient''s nurse"]', 1, 'Guardians are the "surrogates of last resort" when no family or designated proxy is available.'),
    (v_topic_id, 'Which of the following is NOT typically included in a standard "Living Will"?', '["Preferences for CPR", "Instructions for organ donation", "Who should get the patient''s house", "Preferences for artificial nutrition and hydration"]', 2, 'A Living Will is a medical document; the distribution of property is handled in a "Last Will and Testament."'),
    (v_topic_id, 'A patient is an "Unrepresented" or "Unbefriended" patient if they:', '["Have no insurance", "Lacks capacity, has no advance directive, and has no identifiable family or friends to act as a surrogate", "Is homeless", "None of the above"]', 1, 'Unrepresented patients pose a significant ethical challenge and often require hospital ethics committee review or court involvement for major decisions.'),
    (v_topic_id, 'What does the term "Clear and Convincing Evidence" refer to in the context of end-of-life law?', '["Evidence that the patient was a good person", "A high legal standard of proof required in some states to withdraw life support in the absence of a written directive", "A signed confession", "None of the above"]', 1, 'This standard (from the Cruzan case) allows states to require very strong proof (like clear oral statements) before allowing the withdrawal of life-sustaining care.'),
    (v_topic_id, 'A "Value History" is a tool used to:', '["Track a patient''s bank account", "Explore a patient''s underlying beliefs and values to help guide future medical decisions", "List the patient''s previous surgeries", "None of the above"]', 1, 'Value histories go beyond simple treatment checkboxes to understand *why* a patient might want or not want certain care.'),
    (v_topic_id, 'Which of the following can "Override" a DPOA-HC''s decision in most cases?', '["The patient''s neighbor", "The patient, if they regain capacity", "The patient''s priest", "The hospital CEO"]', 1, 'The proxy''s authority is entirely dependent on the patient''s incapacity. If the patient regains capacity, the proxy no longer has power.'),
    (v_topic_id, 'A patient wants to name their "15-year-old son" as their DPOA-HC. Is this valid?', '["Yes, he knows the patient best", "No, surrogates must typically be adults (18 or older)", "Only if the son is a genius", "Only in emergencies"]', 1, 'Legal surrogates must have attained the age of majority to have the legal capacity to make medical decisions for another.'),
    (v_topic_id, 'What is a "Non-hospital DNR" (Comfort Care) bracelet?', '["A piece of jewelry", "A state-approved identifier that tells EMS not to resuscitate the patient", "An insurance tracker", "None of the above"]', 1, 'Specific identifiers like bracelets or purple forms are used to quickly communicate DNR status to emergency responders in the community.'),
    (v_topic_id, 'Which of the following is a common reason for an advance directive to be "Inoperative" in a clinical setting?', '["The document is too old", "The patient currently has decision-making capacity", "The document is written in pencil", "None of the above"]', 1, 'If a patient can speak for themselves, the directive is "dormant."'),
    (v_topic_id, 'Can a DPOA-HC decide to "Enroll a patient in a research study"?', '["No, never", "Yes, if the patient''s advance directive allows it and the study meets specific ethical and legal criteria for surrogate consent", "Only if it pays well", "None of the above"]', 1, 'Surrogates can sometimes consent to research, but this is governed by strict additional protections (e.g., minimal risk or potential for direct benefit).'),
    (v_topic_id, 'A patient is a "Jehovah''s Witness" and has an advance directive refusing blood. They are now unconscious and bleeding. Should the doctor give blood?', '["Yes, save their life", "No, the patient''s valid and specific refusal of blood based on religious beliefs must be honored", "Only if the family agrees", "Only if it is a small amount"]', 1, 'Refusal of blood by a competent adult (or via a valid directive) is a well-established right in both law and ethics.'),
    (v_topic_id, 'What is the "Hierarchy of Surrogates" in most default surrogate laws?', '["Children, then Spouse, then Parents", "Spouse, then Adult Children, then Parents, then Siblings", "Parents, then Spouse, then Children", "The doctor, then the family"]', 1, 'While it varies by state, the standard hierarchy is Spouse -> Adult Children -> Parents -> Siblings.'),
    (v_topic_id, 'Which of the following is NOT a valid way to "Cancel" an advance directive?', '["Tearing up the document", "Verbally telling your doctor you don''t want it anymore", "Asking your neighbor to cancel it for you", "Signing a new, contradictory directive"]', 2, 'Revocation must be done by the patient themselves through a clear act of intent (physical destruction, verbal statement, or a new document).'),
    (v_topic_id, 'A patient has a "DPOA-HC" and a "Living Will." If the two conflict, which one typically takes precedence?', '["The Living Will", "The DPOA-HC (as they are the contemporary interpreter of the patient''s wishes)", "The doctor", "The court"]', 1, 'In most jurisdictions, the proxy has the power to interpret the patient''s wishes in light of current medical reality, which may override a static, older Living Will.'),
    (v_topic_id, 'Can a "Mental Health" advance directive exist?', '["No", "Yes, it allows patients with recurring mental illness (like bipolar disorder) to specify their treatment preferences during future periods of crisis", "Only for dementia", "None of the above"]', 1, 'Also known as "Ulysses Contracts," these are increasingly used to help patients maintain control over their psychiatric care.'),
    (v_topic_id, 'Which ethical principle supports the idea that a patient''s "Past Self" can control their "Future Self"?', '["Justice", "Precedent Autonomy (Prospective Autonomy)", "Paternalism", "None of the above"]', 1, 'Advance directives are the operationalization of precedent autonomy.'),
    (v_topic_id, 'What is the primary risk of a "Checkbox" style Living Will?', '["It is too long", "It lacks the nuance and context needed to guide complex medical decisions in unpredictable scenarios", "It is too expensive", "None of the above"]', 1, 'Simple "yes/no" checkboxes often fail to capture the complexity of a patient''s values in real-world clinical situations.'),
    (v_topic_id, 'Which of the following is a "Clinical" sign that a patient might be nearing the end of life?', '["Increased thirst", "Social withdrawal and sleeping more", "Increased physical activity", "Improved memory"]', 1, 'A natural withdrawal from the environment and increased somnolence are common in the weeks/days before death.'),
    (v_topic_id, 'A "Medical Durable Power of Attorney" is the same as:', '["A bank account", "A Healthcare Proxy / DPOA-HC", "A driver''s license", "None of the above"]', 1, 'The terminology varies by state, but the function of designating a surrogate is the same.'),
    (v_topic_id, 'Does an advance directive need to be "Notarized" to be valid in every state?', '["Yes, always", "No, many states allow the document to be valid if it is signed by two competent adult witnesses instead", "Only for rich people", "None of the above"]', 1, 'Requirements vary, but witnessing is often a valid alternative to notarization.'),
    (v_topic_id, 'A "MOLST" form stands for:', '["Medical Orders for Life-Sustaining Treatment", "Many Others Love Some Treatment", "Medical Organization for Life Support", "None of the above"]', 0, 'MOLST is the version of POLST used in states like New York and Maryland.'),
    (v_topic_id, 'Which of the following is TRUE about advance directives for "Pregnant" patients?', '["They are always honored", "Some states have controversial laws that invalidate a woman''s advance directive (like a DNR) if she is pregnant and the fetus is viable", "Pregnant women cannot have advance directives", "None of the above"]', 1, 'Pregnancy-exclusion laws exist in some states, creating complex ethical and legal conflicts between maternal autonomy and fetal life.'),
    (v_topic_id, 'A patient is "Brain Dead." Does their DPOA-HC have the authority to demand they be kept on a ventilator indefinitely?', '["Yes, they are the proxy", "No, legally and medically, brain death is death; the proxy''s role is typically to coordinate organ donation or the removal of support", "Only if they pay for it", "None of the above"]', 1, 'Once death (brain death) is declared, the patient is no longer a "patient" in the clinical sense, and life-sustaining treatment is no longer a medical option, though a short delay for family grieving or organ donation is common.'),
    (v_topic_id, 'The "Quinlan" case (1976) involved a patient in a:', '["Persistent Vegetative State", "Brain dead state", "Coma from which she recovered", "None of the above"]', 0, 'Karen Ann Quinlan was in a PVS; the case established the right of surrogates to request the removal of life-sustaining treatment (a ventilator).'),
    (v_topic_id, 'A patient''s advance directive says: "I want everything done." The doctor believes a specific treatment is "Futile" (will not work). What should happen?', '["The doctor must do it", "Communication and mediation (e.g., an ethics committee) should be used to resolve the conflict between the patient''s wishes and the doctor''s professional integrity", "The doctor should just quit", "None of the above"]', 1, 'Cases of "Medical Futility" or "Inappropriate Care" are complex and require a multi-step process for resolution, as no one can be forced to provide non-beneficial care.'),
    (v_topic_id, 'Which of the following describes "Substituted Judgment"?', '["Doing what the doctor thinks is best", "Choosing what the patient would have chosen if they were able to speak", "Following the rules exactly", "None of the above"]', 1, 'This is the standard for surrogates when the patient''s specific wishes for the current situation are not explicitly known but their values are.'),
    (v_topic_id, 'A patient is dying and the DPOA-HC asks for "Comfort Care only." The patient''s distant cousin arrives and threatens to sue to "keep them alive." What should the physician do?', '["Follow the cousin''s threat", "Support and follow the DPOA-HC''s decision, as they are the legal decision-maker", "Call the police on the cousin", "None of the above"]', 1, 'Legal and ethical clarity on who the surrogate is protects the patient''s wishes from being overridden by emotional or legally irrelevant family members.')
